"""Existing bounded reader-process enclosure; no Native/JVM command dispatch."""
import time,resource
START=time.monotonic()
def cpu():return sum(r.ru_utime+r.ru_stime for r in (resource.getrusage(resource.RUSAGE_SELF),resource.getrusage(resource.RUSAGE_CHILDREN)))
CPU0=cpu()
from pathlib import Path
import argparse,sys,signal
ROOT=next(p for p in Path(__file__).resolve().parents if (p/'autorouter/pipeline.py').is_file());sys.path.insert(0,str(ROOT));sys.dont_write_bytecode=True
from autorouter import pipeline as p,floor_route as f,handoff as h
from autorouter.runner import run
from experiments.fanout_baseline_v1 import pair as c,continuation as owned
HERE=Path(__file__).resolve().parent


def main(x):
    out=h.real_path(x.output,existing=False);out.mkdir();owner={};h.capture_destination(owner,out)
    argv=[*f.SANDBOX,str(ROOT/'.venv/bin/python'),'-B',str(HERE/'read.py'),'--source-head',x.source_head,'--protocol-sha256',x.protocol_sha256,'--output',str(out)]
    process=run(argv,cwd=out,log=out/'command.log',timeout=85,max_log_bytes=256*1024,max_workdir_bytes=64*1024**2,max_group_rss_bytes=1024**3)
    path=out/'reader.json';pin=p.sha(path) if path.is_file() else None;child=f.read_json(path) if pin else None;literal=f.canonical(child)
    witness=c.shared.material(out);record=dict(schema=1,accepted=False,passed=False,status='failed',git_head=x.source_head,process=process,reader_receipt_sha256=pin,reader_literal=literal,completed_evidence=witness,
        delivery_qualification_pending_external_complete_reader_bound=True,cost_scope='Actual exited reader child below; enclosing stored self totals sampled only. Root must prove complete external wrapper <=90wall/fullCPU; no sample+2 substitute.')
    ok=bool(child and child.get('replay_passed') is True and process['status']=='success' and process['exit_code']==0 and process['cleanup_complete'] is True and not process['log_truncated'])
    record.update(passed=ok,status='completed' if ok else 'cancelled' if process['status']=='cancelled' else 'failed')
    def remaining():return min(90-(time.monotonic()-START),90-(cpu()-CPU0))
    def stable():
        h.owned_destination(owner)
        if c.shared.material(out)!=witness or child is not None and (p.sha(path)!=pin or f.canonical(f.read_json(path))!=literal):raise p.Rejected('reader process outputs changed')
        if child and child.get('replay_passed'):
            if type(child.get('exact_read_inputs_sha256'))is not dict or not child['exact_read_inputs_sha256'] or type(child.get('materials'))is not dict:raise p.Rejected('reader input witnesses missing')
            for name,digest in child['exact_read_inputs_sha256'].items():
                if p.sha(Path(name))!=digest:raise p.Rejected('reader source changed after pure child exit')
            for name,expected in child['materials'].items():
                if c.shared.material(Path(name))!=expected:raise p.Rejected('reader material changed after pure child exit')
        plan=f.read_json(c.PROTOCOL);c.context(plan,x.protocol_sha256);owned.check_prior_witness();c.check_control_prl(plan)
        if child:
            for project,angle in c.ORDER:
                route=c.OUT/project/angle/'child/route';receipt=route/'result.json'
                if receipt.is_file():c.ls.check_normal_policy(route,f.read_json(receipt),max_bytes=c.LIMITS['output'],max_files=2048)
    def account():
        record.update(sampled_wall_seconds=time.monotonic()-START,sampled_full_cpu_seconds=cpu()-CPU0)
        if remaining()<=0 and record['status']!='cancelled':record.update(status='budget_exceeded',passed=False)
        if record['status']!='completed':record['passed']=False
    f.publish(out,record,stable,account,remaining,owned=lambda:h.owned_destination(owner),final_check=stable)
    return 0 if record['passed'] else 2


if __name__=='__main__':
    a=argparse.ArgumentParser(description=__doc__);a.add_argument('--source-head',required=True);a.add_argument('--protocol-sha256',required=True);a.add_argument('--output',type=Path,required=True);x=a.parse_args()
    previous={s:signal.getsignal(s) for s in (signal.SIGINT,signal.SIGTERM)}
    def cancel(*_):raise KeyboardInterrupt
    try:
        for s in previous:signal.signal(s,cancel)
        raise SystemExit(main(x))
    finally:
        for s,v in previous.items():signal.signal(s,v)
